	@Test
	void startingSelectionChecksConnectedPairsOutsideTheThreeCheapestCandidates() throws Exception {
		String query = "SELECT * WHERE { "
				+ "?primary <urn:primary-a> <urn:a> . "
				+ "?primary <urn:primary-b> <urn:b> . "
				+ "?primary <urn:primary-c> <urn:c> . "
				+ "?rare <urn:rare-d> <urn:d> . "
				+ "?rare <urn:rare-e> <urn:e> . "
				+ "?noise <urn:noise-f> <urn:f> . "
				+ "?noise <urn:noise-g> <urn:g> . "
				+ "?noise <urn:noise-h> <urn:h> . }";
		ParsedTupleQuery parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null);
		CountingListTripleSource optimizedSource = new CountingListTripleSource(startingFixtureStatements());
		QueryRoot root = new QueryRoot(parsed.getTupleExpr());
		StartingFixtureStatistics statistics = new StartingFixtureStatistics();
		new QueryJoinOptimizer(statistics, optimizedSource)
				.optimize(root, null, EmptyBindingSet.getInstance());
		assertThat(statistics.joinEstimationCalls)
				.as("the fixture must exercise the join-estimation branch used by the >6 candidate fast path")
				.isGreaterThan(0);

		List<BindingSet> optimizedResults = evaluate(root, optimizedSource);
		CountingListTripleSource idealSource = new CountingListTripleSource(startingFixtureStatements());
		ParsedTupleQuery idealParsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
				queryWithRarePairFirst(), null);
		List<BindingSet> idealResults = evaluate(idealParsed.getTupleExpr(), idealSource);
		assertThat(optimizedResults).containsExactlyInAnyOrderElementsOf(idealResults);
		assertThat(optimizedSource.statementsYielded)
				.as("the optimizer's chosen starting pair must not cause extra fixture work (optimized=%s, ideal=%s)",
						optimizedSource.statementsYielded, idealSource.statementsYielded)
				.isLessThanOrEqualTo(idealSource.statementsYielded);

		List<String> firstPair = statementPredicates(root).stream().limit(2).collect(Collectors.toList());
		assertThat(firstPair)
				.as("the globally cheapest connected pair must be considered even when it is outside the three cheapest starts")
				.containsExactlyInAnyOrder("urn:rare-d", "urn:rare-e");
	}

	@Test
	void positiveLengthPathExportsItsIntermediateBindingWhenTheEvaluatorDoes() throws Exception {
		StatementPattern pathStep = new StatementPattern(Var.of("start"),
				Var.of("path", VF.createIRI("urn:path")), Var.of("intermediate"));
		org.eclipse.rdf4j.query.algebra.ArbitraryLengthPath path = new org.eclipse.rdf4j.query.algebra.ArbitraryLengthPath(
				Var.of("start"), pathStep, Var.of("end"), 1);

		Object visitor = buildJoinVisitor(new QueryJoinOptimizer(new EvaluationStatistics(), emptyTripleSource()));
		Method getBindingInfo = findDeclaredMethod(visitor.getClass(), "getBindingInfo", TupleExpr.class);
		getBindingInfo.setAccessible(true);
		Object bindingInfo = getBindingInfo.invoke(visitor, path);
		Field mayOutput = bindingInfo.getClass().getDeclaredField("mayOutput");
		mayOutput.setAccessible(true);
		Field guaranteedOutput = bindingInfo.getClass().getDeclaredField("guaranteedOutput");
		guaranteedOutput.setAccessible(true);

		// The public algebra contract exposes the inner path variables for a positive-length path. This test is a
		// non-reproduction guard for the corresponding connectedness input; the zero-length case is covered separately.
		assertThat(path.getBindingNames()).containsExactlyInAnyOrder("start", "path", "intermediate", "end");
		assertThat(mayOutput.get(bindingInfo)).as("positive-length paths may expose inner bindings")
				.isEqualTo(Set.of("start", "path", "intermediate", "end"));
		assertThat(guaranteedOutput.get(bindingInfo)).as("positive-length paths guarantee inner bindings")
				.isEqualTo(Set.of("start", "path", "intermediate", "end"));

		ListTripleSource source = new ListTripleSource(List.of(
				VF.createStatement(VF.createIRI("urn:s"), VF.createIRI("urn:path"), VF.createIRI("urn:i"))));
		DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source, null);
		List<BindingSet> results = new ArrayList<>();
		try (CloseableIteration<BindingSet> iteration = strategy.evaluate(path, EmptyBindingSet.getInstance())) {
			while (iteration.hasNext()) {
				results.add(iteration.next());
			}
		}
		assertThat(results).hasSize(1);
		assertThat(results.getFirst().getBindingNames()).contains("start", "path", "intermediate", "end");
	}

	@Test
	void parsedPositiveLengthSequencePathKeepsItsConsumerSemantics() throws Exception {
		String query = "SELECT * WHERE { ?s (<urn:p1>/<urn:p2>)+ ?o . ?o <urn:consumer> ?x . }";
		ParsedTupleQuery parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null);
		List<ArbitraryLengthPath> paths = new ArrayList<>();
		parsed.getTupleExpr().visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(ArbitraryLengthPath node) {
				paths.add(node);
			}
		});
		assertThat(paths).hasSize(1);
		assertThat(paths.getFirst().getMinLength()).isEqualTo(1);
		assertThat(paths.getFirst().getBindingNames()).contains("s", "o");

		List<Statement> statements = List.of(
				VF.createStatement(VF.createIRI("urn:s"), VF.createIRI("urn:p1"), VF.createIRI("urn:mid")),
				VF.createStatement(VF.createIRI("urn:mid"), VF.createIRI("urn:p2"), VF.createIRI("urn:o")),
				VF.createStatement(VF.createIRI("urn:o"), VF.createIRI("urn:consumer"), VF.createIRI("urn:x")));
		CountingListTripleSource source = new CountingListTripleSource(statements);
		QueryRoot root = new QueryRoot(parsed.getTupleExpr());
		new QueryJoinOptimizer(new EvaluationStatistics(), source)
				.optimize(root, null, EmptyBindingSet.getInstance());

		List<BindingSet> results = evaluate(root, source);
		assertThat(results).hasSize(1);
		assertThat(results.getFirst().getValue("s")).isEqualTo(VF.createIRI("urn:s"));
		assertThat(results.getFirst().getValue("o")).isEqualTo(VF.createIRI("urn:o"));
		assertThat(results.getFirst().getValue("x")).isEqualTo(VF.createIRI("urn:x"));
	}

	@Test
	void differenceRightVariablesAreIncorrectlyExposedAsOuterCostConnections() {
		Difference difference = new Difference(
				constantPattern("left", "urn:difference-left", "urn:left"),
				constantPattern("hidden", "urn:difference-right", "urn:right"));
		StatementPattern hiddenConsumer = constantPattern("hidden", "urn:hidden-consumer", "urn:consumer");
		StatementPattern cheap = constantPattern("cheap", "urn:cheap", "urn:cheap-object");

		QueryRoot root = new QueryRoot(new Join(new Join(difference, hiddenConsumer), cheap));
		new QueryJoinOptimizer(new DifferenceCostStatistics(), emptyTripleSource()).optimize(root, null, null);

		List<TupleExpr> leaves = flattenJoinLeaves(root.getArg());
		assertThat(predicate(leaves.getFirst()))
				.as("a MINUS right-only variable must not make its consumer appear connected")
				.isNotEqualTo("urn:hidden-consumer");
	}

