	@ParameterizedTest(name = "{0}")
	@MethodSource("computedBindCases")
	void computedBindOutputCanBeMissedAsAConnectedCostOpportunity(String expression, Value expectedValue)
			throws Exception {
		String query = "SELECT * WHERE { VALUES ?a { <urn:a> } BIND(" + expression + " AS ?b) "
				+ "?x <urn:cheap> ?y . ?s <urn:q> ?b . }";
		ParsedTupleQuery parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null);
		CountingListTripleSource optimizedSource = new CountingListTripleSource(bindFixtureStatements(expectedValue));
		QueryRoot root = new QueryRoot(parsed.getTupleExpr());
		new QueryJoinOptimizer(new BindCostStatistics(), optimizedSource)
				.optimize(root, null, EmptyBindingSet.getInstance());

		List<BindingSet> optimizedResults = evaluate(root, optimizedSource);
		CountingListTripleSource idealSource = new CountingListTripleSource(bindFixtureStatements(expectedValue));
		ParsedTupleQuery idealParsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
				"SELECT * WHERE { VALUES ?a { <urn:a> } BIND(" + expression + " AS ?b) "
						+ "?s <urn:q> ?b . ?x <urn:cheap> ?y . }",
				null);
		List<BindingSet> idealResults = evaluate(idealParsed.getTupleExpr(), idealSource);
		assertThat(optimizedResults).containsExactlyInAnyOrderElementsOf(idealResults);
		assertThat(optimizedSource.statementsYielded)
				.as("losing the deterministic BIND binding must cause extra physical work (optimized=%s, ideal=%s)",
						optimizedSource.statementsYielded, idealSource.statementsYielded)
				.isLessThanOrEqualTo(idealSource.statementsYielded);

		List<String> predicates = statementPredicates(root);
		assertThat(predicates)
				.as("a total BIND result from a guaranteed input is a connected cost opportunity")
				.containsExactly("urn:q", "urn:cheap");
	}

